<?php
namespace App\Http\Controllers; use App\Models\Post; use App\Models\Career;
class ContentController {public function blog(){return view('blog.index',['posts'=>Post::with('translations')->where('status','published')->latest('published_at')->paginate(12)]);} public function post(string $locale,string $slug){$post=Post::with('translations')->whereHas('translations',fn($q)=>$q->where('locale',$locale)->where('slug',$slug))->firstOrFail();return view('blog.show',compact('post'));} public function careers(){return view('careers.index',['careers'=>Career::with('translations')->where('status','published')->paginate(20)]);} public function career(string $locale,string $slug){$career=Career::with('translations')->whereHas('translations',fn($q)=>$q->where('locale',$locale)->where('slug',$slug))->firstOrFail();return view('careers.show',compact('career'));}}
